appearances.css:
.app{padding:6px;border-radius:4px;font-size:9px;display:flex;flex-direction:column;gap:4px}
.app>p{display:none}
.row{margin:0;gap:4px;align-items:flex-end}
.row:nth-child(1)>.control{flex:0 0 96px}
.row:nth-child(2){border:1px solid var(--line,#344953);border-radius:4px;padding:4px 5px}
button,select,input{font-size:8.5px;padding:4px 5px;border-radius:3px}
.row>button{min-width:26px}
.control{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;border:0;padding:0;min-width:0;border-radius:0;flex:1 1 52px}
.control>span:not(.kn){order:3;font-size:7.5px;text-align:center;line-height:1.1;max-width:100%;letter-spacing:-.02em}
.control>output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap}
.control>.kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
.control>select,.control>input[type=text]{order:1;width:100%;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;cursor:pointer}
.control>input[type=text]{cursor:text;padding:3px 4px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(46px,1fr));gap:3px 4px;border:1px solid var(--line,#344953);border-radius:4px;padding:5px;margin:0;align-items:end}
.row+.row+.grid{grid-template-columns:repeat(12,minmax(0,1fr))}
.row+.row+.grid>.control{grid-column:span 1;order:2}
.row+.row+.grid>.control:nth-child(1),.row+.row+.grid>.control:nth-child(2),.row+.row+.grid>.control:nth-child(3),.row+.row+.grid>.control:nth-child(5),.row+.row+.grid>.control:nth-child(6),.row+.row+.grid>.control:nth-child(7){grid-column:span 2;order:1}
.row+.row+.grid>.control:nth-child(13){grid-column:span 6}
.pads{grid-template-columns:repeat(16,minmax(0,1fr));gap:2px}
.pads button{min-height:0;height:30px;padding:2px;font-size:7.5px;line-height:1.1;border-radius:3px}
h3{font-size:7px;margin:2px 0 0;line-height:1}
.mini{gap:2px}
.mini input{height:40px;padding:0}
.mini.w input{height:16px}
canvas{height:160px}
.mini.w+.grid,.row+.grid{grid-template-columns:repeat(3,64px);justify-content:start}
